// Generated by Skyramp v1.3.40
// Scenario: library-reset-confirm-clears-items

// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import {
    addSelectionToLibrary,
    confirmResetLibrary,
    drawRectangle,
    openLibraryDropdown,
    openLibrarySidebar,
} from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(299000);

    // set default timeout for all locator/page actions in this test
    // assertions reviewed: the enhance rules target HTTP response bodies after sendRequest calls; this
    // trace issues no HTTP requests, so none apply. State coverage is already present: the empty-state
    // text plus toHaveCount(1) on the dropdown entries pin the cleared library from two directions.
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');

    await drawRectangle(page, 400, 300, 560, 420);
    await openLibrarySidebar(page);
    await addSelectionToLibrary(page);
    await openLibraryDropdown(page);
    await confirmResetLibrary(page);

    // Confirming clears the whole personal library.
    await expect(page.getByText("No items added yet...")).toBeVisible();

    // With no items left, the dropdown drops back to a single entry (Open).
    await openLibraryDropdown(page);
    await expect(page.getByRole("menuitem")).toHaveCount(1);
});
